static const McPacketCatalog *find_packet_catalog(int protocol)
{
    size_t count = sizeof(packet_catalogs) / sizeof(packet_catalogs[0]);
    for (size_t index = 0U; index < count; ++index) {
        if (packet_catalogs[index].protocol == protocol) return &packet_catalogs[index];
    }
    return NULL;
}

static const McPacketMap *packet_map(const McPacketCatalog *catalog,
    McState state, McPacketDirection direction)
{
    if (catalog == NULL
        || (direction != MC_PACKET_SERVERBOUND
            && direction != MC_PACKET_CLIENTBOUND)) return NULL;
    bool serverbound = direction == MC_PACKET_SERVERBOUND;
    switch (state) {
    case MC_STATE_LOGIN:
        return serverbound ? &catalog->login_serverbound : &catalog->login_clientbound;
    case MC_STATE_CONFIGURATION:
        return serverbound ? &catalog->configuration_serverbound
                           : &catalog->configuration_clientbound;
    case MC_STATE_PLAY:
        return serverbound ? &catalog->play_serverbound : &catalog->play_clientbound;
    case MC_STATE_STATUS:
        return serverbound ? &packet_map_status_serverbound
                           : &packet_map_status_clientbound;
    default:
        return NULL;
    }
}


/* ============================================================
 * INTERNAL TYPES
 * ============================================================ */

/* The public reader is also the internal packet cursor. Keeping one bounded
 * implementation prevents login, compression and application codecs from
 * disagreeing about malformed VarInts or buffer limits. */
typedef McReader McCursor;

typedef struct {
    unsigned char *data;
    size_t size;
} McFrame;

#if defined(__linux__)
typedef struct {
    int fd;
    void *sq_map;
    void *cq_map;
    struct io_uring_sqe *sqes;
    size_t sq_map_size;
    size_t cq_map_size;
    size_t sqes_size;
    unsigned int *sq_head;
    unsigned int *sq_tail;
    unsigned int *sq_mask;
    unsigned int *sq_array;
    unsigned int *cq_head;
    unsigned int *cq_tail;
    unsigned int *cq_mask;
    struct io_uring_cqe *cqes;
    bool single_map;
} McRing;
#endif

struct McClient {
    atomic_int socket_fd;
    atomic_bool stop;
    const McProfile *profile;
    McCallbacks callbacks;
    void *userdata;
    McState state;
    McBackend backend;
    McBackend preferred_backend;
    int event_fd;
    int compression_threshold;
    uint64_t sent_bytes;
    uint64_t received_bytes;
    uint32_t automatic_replies;
    unsigned int read_timeout_ms;
    McStreamTransforms transforms;
    McStreamDecoder *stream_decoder;
    struct sockaddr_storage local_address;
    socklen_t local_address_size;
    bool player_loaded_sent;
    bool server_side;
#if defined(__linux__)
    McRing ring;
#endif
};

struct McServer {
    int socket_fd;
    uint16_t port;
};

/* Error buffers belong to the caller. Treating a missing buffer as a valid
 * choice lets applications ignore diagnostic text without separate APIs. */
#if defined(__GNUC__) || defined(__clang__)
static void set_error(char *error, size_t size, const char *format, ...)
    __attribute__((format(printf, 3, 4)));
#endif
static void set_error(char *error, size_t size, const char *format, ...)
{
    if (error == NULL || size == 0U) return;
    va_list arguments;
    va_start(arguments, format);
    (void)vsnprintf(error, size, format, arguments);
    va_end(arguments);
}

static const McProfile *find_profile(int protocol)
{
    size_t count = sizeof(profiles) / sizeof(profiles[0]);
    for (size_t index = 0U; index < count; ++index) {
        if (profiles[index].protocol == protocol) return &profiles[index];
    }
    return NULL;
}


/* ============================================================
 * ERROR MODEL
 * ============================================================ */

void mc_error_clear(McError *error)
{
    if (error == NULL) return;
    *error = (McError){
        .code = MC_ERROR_NONE,
        .offset = MC_ERROR_OFFSET_UNKNOWN,
        .protocol = -1,
        .state = MC_STATE_UNKNOWN,
        .direction = MC_PACKET_DIRECTION_UNKNOWN,
        .packet_id = -1,
    };
}

const char *mc_error_name(McErrorCode code)
{
    switch (code) {
    case MC_ERROR_NONE: return "MC_ERROR_NONE";
    case MC_ERROR_INVALID_ARGUMENT: return "MC_ERROR_INVALID_ARGUMENT";
    case MC_ERROR_UNSUPPORTED_PROTOCOL: return "MC_ERROR_UNSUPPORTED_PROTOCOL";
    case MC_ERROR_INVALID_STATE: return "MC_ERROR_INVALID_STATE";
    case MC_ERROR_INVALID_DIRECTION: return "MC_ERROR_INVALID_DIRECTION";
    case MC_ERROR_UNKNOWN_PACKET: return "MC_ERROR_UNKNOWN_PACKET";
    case MC_ERROR_PARTIAL_INPUT: return "MC_ERROR_PARTIAL_INPUT";
    case MC_ERROR_VARINT_OVERFLOW: return "MC_ERROR_VARINT_OVERFLOW";
    case MC_ERROR_VARINT_NON_CANONICAL: return "MC_ERROR_VARINT_NON_CANONICAL";
    case MC_ERROR_FRAME_TOO_LARGE: return "MC_ERROR_FRAME_TOO_LARGE";
    case MC_ERROR_BUFFER_LIMIT: return "MC_ERROR_BUFFER_LIMIT";
    case MC_ERROR_DECOMPRESSED_TOO_LARGE:
        return "MC_ERROR_DECOMPRESSED_TOO_LARGE";
    case MC_ERROR_COMPRESSION_HEADER: return "MC_ERROR_COMPRESSION_HEADER";
    case MC_ERROR_COMPRESSION_THRESHOLD: return "MC_ERROR_COMPRESSION_THRESHOLD";
    case MC_ERROR_ZLIB: return "MC_ERROR_ZLIB";
    case MC_ERROR_TRAILING_BYTES: return "MC_ERROR_TRAILING_BYTES";
    case MC_ERROR_INVALID_BOOLEAN: return "MC_ERROR_INVALID_BOOLEAN";
    case MC_ERROR_STRING_TOO_LARGE: return "MC_ERROR_STRING_TOO_LARGE";
    case MC_ERROR_NBT_DEPTH: return "MC_ERROR_NBT_DEPTH";
    case MC_ERROR_NBT_LENGTH: return "MC_ERROR_NBT_LENGTH";
    case MC_ERROR_INVALID_LENGTH: return "MC_ERROR_INVALID_LENGTH";
    case MC_ERROR_INTEGER_OVERFLOW: return "MC_ERROR_INTEGER_OVERFLOW";
    case MC_ERROR_INVALID_PACKET_BODY: return "MC_ERROR_INVALID_PACKET_BODY";
    case MC_ERROR_OUT_OF_MEMORY: return "MC_ERROR_OUT_OF_MEMORY";
    case MC_ERROR_IO: return "MC_ERROR_IO";
    case MC_ERROR_TIMEOUT: return "MC_ERROR_TIMEOUT";
    case MC_ERROR_INTERNAL: return "MC_ERROR_INTERNAL";
    }
    return "MC_ERROR_UNKNOWN";
}

static void record_error(McError *error, McErrorCode code, size_t offset)
{
    if (error == NULL || error->code != MC_ERROR_NONE) return;
    error->code = code;
    error->offset = offset;
}

static bool reader_fail(McReader *reader, McErrorCode code, size_t offset)
{
    if (reader != NULL && !reader->failed) {
        record_error(reader->error, code, offset);
        reader->failed = true;
    }
    return false;
}

static bool reader_fail_protocol(McReader *reader, McErrorCode code,
    size_t offset, int protocol)
{
    const bool result = reader_fail(reader, code, offset);
    if (reader != NULL && reader->error != NULL) {
        reader->error->protocol = protocol;
    }
    return result;
}


/* ============================================================
 * PACKET REGISTRY
 * ============================================================ */

/* Registry objects are static and immutable. Returning their pointers avoids
 * allocation while giving callers stable names suitable for dispatch tables. */
const int *mc_supported_protocols(size_t *count)
{
    if (count != NULL) *count = sizeof(protocol_ids) / sizeof(protocol_ids[0]);
    return protocol_ids;
}

bool mc_protocol_supported(int protocol)
{
    return find_profile(protocol) != NULL;
}

const char *mc_protocol_name(int protocol)
{
    size_t count = sizeof(protocol_ids) / sizeof(protocol_ids[0]);
    for (size_t index = 0U; index < count; ++index) {
        if (protocol_ids[index] == protocol) return protocol_names[index];
    }
    return NULL;
}

int mc_protocol_by_name(const char *release_name)
{
    if (release_name == NULL) return -1;
    size_t count = sizeof(protocol_names) / sizeof(protocol_names[0]);
    for (size_t index = 0U; index < count; ++index) {
        if (strcmp(protocol_names[index], release_name) == 0) {
            return protocol_ids[index];
        }
    }
    return -1;
}

uint32_t mc_protocol_features(int protocol)
{
    const McProfile *profile = find_profile(protocol);
    return profile != NULL ? profile->flags : 0U;
}

size_t mc_packet_count(int protocol)
{
    const McPacketCatalog *catalog = find_packet_catalog(protocol);
    if (catalog == NULL) return 0U;
    return catalog->login_serverbound.count + catalog->login_clientbound.count
        + catalog->configuration_serverbound.count
        + catalog->configuration_clientbound.count
        + catalog->play_serverbound.count + catalog->play_clientbound.count
        + sizeof(packet_names_status_serverbound)
            / sizeof(packet_names_status_serverbound[0])
        + sizeof(packet_names_status_clientbound)
            / sizeof(packet_names_status_clientbound[0]);
}

bool mc_packet_at(int protocol, size_t index, McPacketInfo *packet)
{
    const McPacketCatalog *catalog = find_packet_catalog(protocol);
    if (catalog == NULL || packet == NULL) return false;
    const McPacketMap *maps[] = {
        &catalog->login_serverbound, &catalog->login_clientbound,
        &catalog->configuration_serverbound, &catalog->configuration_clientbound,
        &catalog->play_serverbound, &catalog->play_clientbound,
        &packet_map_status_serverbound, &packet_map_status_clientbound
    };
    const McState states[] = {
        MC_STATE_LOGIN, MC_STATE_LOGIN,
        MC_STATE_CONFIGURATION, MC_STATE_CONFIGURATION,
        MC_STATE_PLAY, MC_STATE_PLAY,
        MC_STATE_STATUS, MC_STATE_STATUS
    };
    const McPacketDirection directions[] = {
        MC_PACKET_SERVERBOUND, MC_PACKET_CLIENTBOUND,
        MC_PACKET_SERVERBOUND, MC_PACKET_CLIENTBOUND,
        MC_PACKET_SERVERBOUND, MC_PACKET_CLIENTBOUND,
        MC_PACKET_SERVERBOUND, MC_PACKET_CLIENTBOUND
    };
    for (size_t map_index = 0U; map_index < sizeof(maps) / sizeof(maps[0]);
            ++map_index) {
        if (index < maps[map_index]->count) {
            packet->state = states[map_index];
            packet->direction = directions[map_index];
            packet->id = (int32_t)index;
            packet->name = maps[map_index]->names[index];
            return true;
        }
        index -= maps[map_index]->count;
    }
    return false;
}

const char *mc_packet_name(int protocol, McState state,
    McPacketDirection direction, int32_t id)
{
    const McPacketMap *map = packet_map(find_packet_catalog(protocol), state, direction);
    if (map == NULL || id < 0 || (size_t)id >= map->count) return NULL;
    return map->names[id];
}

int32_t mc_packet_id(int protocol, McState state,
    McPacketDirection direction, const char *name)
{
    const McPacketMap *map = packet_map(find_packet_catalog(protocol), state, direction);
    if (map == NULL || name == NULL) return -1;
    for (size_t index = 0U; index < map->count; ++index) {
        if (strcmp(map->names[index], name) == 0) return (int32_t)index;
    }
    return -1;
}

static bool packet_name_is(const char *name, const char *expected)
{
    return name != NULL && strcmp(name, expected) == 0;
}

typedef struct {
    const char *name;
    McPacketFamily family;
} McPacketFamilyName;

static McPacketFamily packet_family_from_table(const char *name,
    const McPacketFamilyName *table, size_t count)
{
    for (size_t index = 0U; index < count; ++index) {
        /* Catalog and family strings normally share the same literal address;
         * keep strcmp as the portable fallback when a compiler does not merge
         * identical constants. */
        if (name == table[index].name || packet_name_is(name, table[index].name)) {
            return table[index].family;
        }
    }
    return MC_FAMILY_UNKNOWN;
}

McPacketFamily mc_packet_family(int protocol, McState state,
    McPacketDirection direction, int32_t packet_id)
{
    static const McPacketFamilyName serverbound[] = {
        {"flying", MC_FAMILY_PLAYER_MOVEMENT},
        {"position", MC_FAMILY_PLAYER_MOVEMENT},
        {"look", MC_FAMILY_PLAYER_MOVEMENT},
        {"position_look", MC_FAMILY_PLAYER_MOVEMENT},
        {"player_input", MC_FAMILY_PLAYER_INPUT},
        {"entity_action", MC_FAMILY_ENTITY_ACTION},
        {"abilities", MC_FAMILY_ABILITIES},
        {"vehicle_move", MC_FAMILY_VEHICLE_MOVE},
        {"steer_vehicle", MC_FAMILY_STEER_VEHICLE},
        {"use_entity", MC_FAMILY_USE_ENTITY},
        {"attack", MC_FAMILY_ATTACK},
        {"arm_animation", MC_FAMILY_ARM_ANIMATION},
        {"block_dig", MC_FAMILY_BLOCK_DIG},
        {"block_place", MC_FAMILY_BLOCK_PLACE},
        {"use_item", MC_FAMILY_USE_ITEM},
        {"held_item_slot", MC_FAMILY_HELD_ITEM_SLOT},
        {"teleport_confirm", MC_FAMILY_TELEPORT_CONFIRM},
        {"window_click", MC_FAMILY_WINDOW_CLICK},
        {"set_creative_slot", MC_FAMILY_SET_CREATIVE_SLOT},
        {"client_command", MC_FAMILY_CLIENT_COMMAND},
        {"close_window", MC_FAMILY_CLOSE_WINDOW},
    };
    static const McPacketFamilyName clientbound[] = {
        {"login", MC_FAMILY_JOIN_GAME},
        {"position", MC_FAMILY_SERVER_POSITION},
        {"entity_velocity", MC_FAMILY_ENTITY_VELOCITY},
        {"explosion", MC_FAMILY_EXPLOSION},
        {"abilities", MC_FAMILY_ABILITIES},
        {"entity_effect", MC_FAMILY_ENTITY_EFFECT},
        {"remove_entity_effect", MC_FAMILY_REMOVE_ENTITY_EFFECT},
        {"update_attributes", MC_FAMILY_UPDATE_ATTRIBUTES},
        {"entity_update_attributes", MC_FAMILY_UPDATE_ATTRIBUTES},
        {"rel_entity_move", MC_FAMILY_RELATIVE_ENTITY_MOVE},
        {"entity_move_look", MC_FAMILY_ENTITY_MOVE_LOOK},
        {"entity_teleport", MC_FAMILY_ENTITY_TELEPORT},
        {"sync_entity_position", MC_FAMILY_ENTITY_TELEPORT},
        {"entity_head_rotation", MC_FAMILY_ENTITY_HEAD_ROTATION},
        {"entity_metadata", MC_FAMILY_ENTITY_METADATA},
        {"attach_entity", MC_FAMILY_ATTACH_ENTITY},
        {"set_passengers", MC_FAMILY_SET_PASSENGERS},
        {"block_change", MC_FAMILY_BLOCK_CHANGE},
        {"multi_block_change", MC_FAMILY_MULTI_BLOCK_CHANGE},
        {"map_chunk", MC_FAMILY_MAP_CHUNK},
        {"unload_chunk", MC_FAMILY_UNLOAD_CHUNK},
        {"set_slot", MC_FAMILY_SET_SLOT},
        {"window_items", MC_FAMILY_WINDOW_ITEMS},
        {"close_window", MC_FAMILY_CLOSE_WINDOW},
        {"held_item_slot", MC_FAMILY_HELD_ITEM_SLOT},
        {"respawn", MC_FAMILY_RESPAWN},
        {"game_state_change", MC_FAMILY_GAME_STATE_CHANGE},
        {"update_time", MC_FAMILY_UPDATE_TIME},
    };
    const char *name = mc_packet_name(protocol, state, direction, packet_id);
    if (name == NULL || state != MC_STATE_PLAY) return MC_FAMILY_UNKNOWN;
    if (direction == MC_PACKET_SERVERBOUND) {
        return packet_family_from_table(name, serverbound,
            sizeof(serverbound) / sizeof(serverbound[0]));
    }
    if (direction != MC_PACKET_CLIENTBOUND) return MC_FAMILY_UNKNOWN;
    return packet_family_from_table(name, clientbound,
        sizeof(clientbound) / sizeof(clientbound[0]));
}

const char *mc_packet_family_name(McPacketFamily family)
{
    static const char *const names[] = {
        "unknown", "player_movement", "player_input", "entity_action",
        "abilities", "vehicle_move", "steer_vehicle", "use_entity",
        "attack", "arm_animation", "block_dig", "block_place", "use_item",
        "held_item_slot", "teleport_confirm", "window_click",
        "set_creative_slot", "client_command", "close_window",
        "server_position", "entity_velocity", "explosion", "entity_effect",
        "remove_entity_effect", "update_attributes", "relative_entity_move",
        "entity_move_look", "entity_teleport", "entity_head_rotation",
        "entity_metadata", "attach_entity", "set_passengers", "block_change",
        "multi_block_change", "map_chunk", "unload_chunk", "set_slot",
        "window_items", "respawn", "game_state_change", "join_game",
        "update_time"
    };
    const size_t count = sizeof(names) / sizeof(names[0]);
    return (int)family >= 0 && (size_t)family < count ? names[family] : "unknown";
}

